use std::collections::HashMap;
use std::io::{self, Write};
use std::process::ExitCode;

/// Running total for one key. Once a running total leaves the i64 range the
/// key stays overflowed, regardless of later records.
#[derive(Clone, Copy)]
enum Total {
    Sum(i64),
    Overflow,
}

/// Splits on '\n' and drops a trailing '\r' so CRLF files behave like LF files.
fn lines(data: &[u8]) -> impl Iterator<Item = &[u8]> {
    let data = data.strip_suffix(b"\n").unwrap_or(data);
    let empty = data.is_empty();
    data.split(|&b| b == b'\n')
        .filter(move |_| !empty)
        .map(|l| l.strip_suffix(b"\r").unwrap_or(l))
}

fn parse_value(bytes: &[u8]) -> Option<i64> {
    std::str::from_utf8(bytes).ok()?.parse().ok()
}

fn run(data: &[u8], out: &mut impl Write) -> io::Result<()> {
    let data = data.strip_prefix(b"\xEF\xBB\xBF").unwrap_or(data);
    let mut totals: HashMap<&[u8], Total> = HashMap::new();
    let mut iter = lines(data);

    for line in iter.by_ref() {
        if line.is_empty() {
            break;
        }
        let Some(sep) = line.iter().position(|&b| b == b' ') else {
            continue;
        };
        let key = &line[..sep];
        let Some(value) = parse_value(line[sep + 1..].trim_ascii()) else {
            continue;
        };
        if key.is_empty() {
            continue;
        }
        let entry = totals.entry(key).or_insert(Total::Sum(0));
        if let Total::Sum(sum) = *entry {
            *entry = match sum.checked_add(value) {
                Some(s) => Total::Sum(s),
                None => Total::Overflow,
            };
        }
    }

    for key in iter {
        let key = key.trim_ascii();
        if key.is_empty() {
            continue;
        }
        out.write_all(key)?;
        match totals.get(key) {
            Some(Total::Sum(s)) => writeln!(out, "={s}")?,
            Some(Total::Overflow) => writeln!(out, "=overflow")?,
            None => writeln!(out, "=absent")?,
        }
    }
    out.flush()
}

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1) else {
        eprintln!("usage: keyed_totals <file>");
        return ExitCode::from(2);
    };
    let data = match std::fs::read(&path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("cannot read {}: {e}", path.to_string_lossy());
            return ExitCode::from(1);
        }
    };
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    match run(&data, &mut out) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("write error: {e}");
            ExitCode::from(1)
        }
    }
}
